import{fetchCohortJSON}from'./current-cohort-loader.js';import{decodeSimulator078}from'./simulator-codec-078.js';import{hydrateSimulator079}from'./simulator-codec-079.js';import{boardOffer}from'./results-board-data.js';import{explorerCatalog}from'./open-explorer.js';import{careerFamilies}from'./guide-state.js';
const cohortLabel=c=>({development:'Original development',holdout:'Original holdout',holdout049:'Earlier fresh holdout',holdout056:'Expansion holdout',grok075:'Grok evaluation cohort'}[c]||c);
const get=id=>document.getElementById(id),frame=get('results-board-frame'),h=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let data=null,current=null,records=[],study,study087,study088,study089,study090,study093;
const viewport=()=>frame.contentWindow.postMessage({type:'fieldguide-board-viewport',top:Math.max(0,-frame.getBoundingClientRect().top)+16,height:Math.max(250,window.innerHeight-48)},location.origin);window.addEventListener('scroll',viewport,{passive:true});window.addEventListener('resize',viewport);
const send=()=>{if(data)frame.contentWindow.postMessage({type:'fieldguide-board-init',data,preview:true},location.origin);};
window.addEventListener('message',e=>{if(e.origin!==location.origin||e.source!==frame.contentWindow)return;const m=e.data;if(m?.type==='fieldguide-board-ready'){send();viewport();}if(m?.type==='fieldguide-board-dialog')viewport();if(m?.type==='fieldguide-board-height'&&Number.isFinite(m.height))frame.style.height=Math.max(800,Math.min(50000,m.height))+'px';if(m?.type==='fieldguide-board-save'){data.saved=m.saved?[...new Set([...(data.saved||[]),m.id])]:(data.saved||[]).filter(id=>id!==m.id);}if(m?.type==='fieldguide-board-navigate'){if(m.route==='journey/lifestyle'){get('status').textContent='Model lifestyle is frozen. Open My Plan to edit your own.';get('status').scrollIntoView();return;}location.href='./student-view.html?case='+encodeURIComponent(current.id)+'&replay=final#/'+m.route;}});frame.addEventListener('load',send);
async function choose(id){const record=records.find(r=>r.id===id);if(!record){get('status').textContent='Choose a model from the list.';return;}current=record;get('status').textContent='Opening '+record.name+'…';if(!study){const [raw,response]=await Promise.all([fetchCohortJSON('./developer/simulator-repair-079.json.gz'),fetch('./developer/simulator-repair-078.json.gz',{cache:'no-store'})]);if(!response.ok)throw Error('Research baseline unavailable');const encoded=decodeSimulator078(raw),bytes=new Uint8Array(await response.arrayBuffer()),hash=[...new Uint8Array(await crypto.subtle.digest('SHA-256',bytes))].map(n=>n.toString(16).padStart(2,'0')).join('');if(hash!==encoded.baselineSHA256)throw Error('Research versions differ; reload this page');const base=JSON.parse(await new Response(new Blob([bytes]).stream().pipeThrough(new DecompressionStream('gzip'))).text());study=hydrateSimulator079(encoded,decodeSimulator078(base));}if(!study087)study087=decodeSimulator078(await fetchCohortJSON('./developer/noncollege-087.json.gz'));if(!study088)study088=decodeSimulator078(await fetchCohortJSON('./developer/evidence-088.json.gz'));if(!study089)study089=decodeSimulator078(await fetchCohortJSON('./developer/evidence-089.json.gz'));if(!study090)study090=decodeSimulator078(await fetchCohortJSON('./developer/evidence-090.json.gz'));if(!study093)study093=await fetchCohortJSON('./developer/evidence-093.json.gz');const current093=study093.rows.find(r=>r.id===id);const current090=study090.rows.find(r=>r.id===id);const current089=study089.rows.find(r=>r.id===id);const current088=study088.rows.find(r=>r.id===id),merged088=new Map((study087.rows.find(r=>r.id===id)?.extra||[]).map(o=>[o.id,o]));for(const o of current088?.extra||[])merged088.set(o.id,o);for(const o of current089?.extra||[])merged088.set(o.id,o);for(const o of current090?.extra||[])merged088.set(o.id,o);const additions087=[...merged088.values()];const row=study.rows.find(r=>r.id===id),catalog=new Map(explorerCatalog.map(o=>[o.id,o]));const pack=(k,i,candidate)=>{const[careerId,r,b,,,contrary]=row.pool[k],o=catalog.get(careerId)||study.catalog[careerId];return boardOffer(o,{rank:i,top:!candidate&&row.after.top.includes(k),candidate,fields:study.catalog[careerId].fields,routes:study.catalog[careerId].routes,amount:study.budgets[b].amount,evidence:record.interests,r,mixed:contrary>0});};data={fields:careerFamilies.map(f=>({id:f.id,title:f.title})),saved:[],profiles:[{...record,firstName:record.name.split(' ')[0],supported:[...row.after.supported.map((k,i)=>pack(k,i,false)),...additions087.filter(o=>!o.candidate)],candidates:[...row.after.candidates.map((k,i)=>pack(k,i,true)),...additions087.filter(o=>o.candidate)],candidateCount:row.after.candidates.length+additions087.filter(o=>o.candidate).length}]};if(current090){const active=new Set(current090.afterTop.map(o=>o.id)),confirmed=new Set(data.profiles[0].supported.map(o=>o.id));data.profiles[0].supported=data.profiles[0].supported.map(o=>({...o,top:active.has(o.id)}));data.profiles[0].candidates=data.profiles[0].candidates.filter(o=>!confirmed.has(o.id));data.profiles[0].candidateCount=data.profiles[0].candidates.length;}if(current093){const currentOffers=new Map([...data.profiles[0].supported,...data.profiles[0].candidates,...current093.extra].map(o=>[o.id,o]));data.profiles[0].supported=current093.supported.map(id=>({...currentOffers.get(id),candidate:false,top:current093.top.includes(id)}));data.profiles[0].candidates=[...currentOffers.values()].filter(o=>!current093.supported.includes(o.id)).map(o=>({...o,candidate:true,top:false}));data.profiles[0].candidateCount=data.profiles[0].candidates.length;}send();get('status').textContent=record.name+' · '+cohortLabel(record.cohort)+' · research replay 0.93 · model changes stay separate from your plan';const u=new URL(location.href);u.searchParams.set('model',id);history.replaceState({},'',u);get('model-choice').value=id;}
get('model-form').addEventListener('submit',e=>{e.preventDefault();choose(get('model-choice').value).catch(fail);});function fail(e){get('status').textContent='Could not open this model: '+e.message;}
try{records=await fetchCohortJSON('./developer/results-board-model-index.json.gz');get('models').innerHTML=records.map(r=>`<option value="${h(r.id)}">${h(r.name)} · ${h(cohortLabel(r.cohort))}</option>`).join('');await choose(new URL(location.href).searchParams.get('model')||'scale056-0061');}catch(e){fail(e);}
if(new URL(location.href).searchParams.get('journey')==='1'){get('model-form').hidden=true;get('model-form').style.display='none';document.querySelector('header').hidden=true;document.querySelector('header').style.display='none';}
